<script setup lang="ts">
import { nextTick, onMounted, onBeforeUnmount, computed, ref } from 'vue'
import {useRoute} from 'vue-router'
import {coaching,teachers} from '@/api/coaching'
import SpeakButton from '@/components/SpeakButton.vue'
import { learningApi } from '@/api/learning'
import { foundation, streamChat, openDocument, type Conversation } from '@/api/foundation'
import { api, messageOf } from '@/api/client'
import type { Citation, KnowledgeBase, ChatResult,RetrievalTrace } from '@/api/types'
import {useAuthStore} from '@/stores/auth'
import SafeAnswer from '@/components/SafeAnswer.vue'
import CitationReader from '@/components/CitationReader.vue'
interface Understanding {question:string;intent:string;knowledge_points:string[]}
interface Message {generation?:import('@/api/types').GenerationTrace;related?:import('@/api/foundation').Asset[];reasoning?:RetrievalTrace; understanding?:Understanding; role: 'user' | 'assistant'; content: string; sources?: Citation[]; failure?:string; incomplete?:boolean }
const route=useRoute(),teacher=ref('encouraging')
async function saveTeacher(){try{await coaching.memory({Key:'teacher',PointID:'',Kind:'preference',Content:teacher.value,Resolved:false})}catch(e){error.value=messageOf(e)}}
const bases = ref<KnowledgeBase[]>([]), active = ref(''), question = ref(''), conversation = ref('')
const busy = ref(false), loading = ref(true), error = ref(''), messages = ref<Message[]>([]), box = ref<HTMLElement>()
const history=ref<Conversation[]>([]),stage=ref(''),controller=ref<AbortController>()
const activeSource=ref<Citation|null>(null),sidebarOpen=ref(false),historySearch=ref(''),followBottom=ref(true),copyNotice=ref(''),versionWarning=ref('')
const visibleHistory=computed(()=>history.value.filter(c=>bases.value.some(b=>b.ID===c.KnowledgeBaseID)&&c.Title.toLowerCase().includes(historySearch.value.toLowerCase())))
function onScroll(){const el=box.value;if(el)followBottom.value=el.scrollHeight-el.scrollTop-el.clientHeight<100}
function resizeInput(event:Event){const el=event.target as HTMLTextAreaElement;el.style.height='auto';el.style.height=Math.min(el.scrollHeight,190)+'px'}
async function copyAnswer(text:string){try{await navigator.clipboard.writeText(text);copyNotice.value='已复制回答';setTimeout(()=>copyNotice.value='',1800)}catch{error.value='复制失败，请选择回答文字后复制'}}
function jumpToBottom(){followBottom.value=true;void nextTick(()=>box.value?.scrollTo({top:box.value.scrollHeight,behavior:'auto'}))}

const auth=useAuthStore(),checking=ref(false),checkReport=ref<{passed:boolean;checks:{name:string;passed:boolean;message:string}[]}|null>(null)
async function checkConnection(){if(checking.value||busy.value)return;checking.value=true;error.value='';checkReport.value=null;try{checkReport.value=(await api.post('/admin/assistant/check',{}, {timeout:195000})).data}catch(e){error.value=messageOf(e)}finally{checking.value=false}}

const imageFile=ref<File|null>(null),imageURL=ref(''),recognizing=ref(false),recognized=ref(false),imageWarnings=ref<string[]>([]),imageMethod=ref('')
const imageController=ref<AbortController>()
function clearImage(){imageController.value?.abort();imageController.value=undefined;if(imageURL.value)URL.revokeObjectURL(imageURL.value);imageURL.value='';imageFile.value=null;recognized.value=false;imageWarnings.value=[];imageMethod.value=''}
function chooseImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;clearImage();if(!['image/png','image/jpeg'].includes(file.type)||file.size>10*1024*1024){error.value='请选择不超过10 MiB的PNG/JPEG题目图片';return};error.value='';imageFile.value=file;imageURL.value=URL.createObjectURL(file)}
async function recognizeImage(){
 if(!imageFile.value||!active.value||recognizing.value||busy.value)return
 recognizing.value=true;error.value='';const file=imageFile.value;imageController.value=new AbortController()
 try{
  const body=new FormData();body.append('file',file);body.append('KnowledgeBaseID',active.value)
  const {data}=await api.post<{text:string;method:string;warnings:string[]}>('/exam408/assistant/recognize',body,{signal:imageController.value.signal,timeout:120000})
  if(imageFile.value!==file)return
  question.value=[question.value.trim(),data.text].filter(Boolean).join('\n\n');recognized.value=true;imageWarnings.value=data.warnings??[];imageMethod.value=data.method
 }catch(e){if(imageFile.value===file)error.value=messageOf(e)}finally{recognizing.value=false}
}

const status = ref({ mode: 'unavailable', enabled: false, message: '' })
async function load() {
 loading.value=true;error.value=''
 try { status.value=await learningApi.assistantStatus();bases.value=(await learningApi.bases()).filter(b=>auth.user?.role!=='admin'||b.IsPublic);history.value=await foundation.conversations();const capabilities=(await api.get('/system/capabilities')).data;versionWarning.value=capabilities.release==='2026.11.08.2'?'':'前端与服务端版本不一致，最新功能尚未完整部署。请管理员拉取源码并重建 backend、worker 和 frontend。';active.value=bases.value[0]?.ID||''
 const saved=history.value.find(c=>c.ID===sessionStorage.getItem('408_conversation'));if(saved)await selectConversation(saved.ID)
 if(typeof route.query.question==='string'){reset();question.value=route.query.question}
 try{const overview=await coaching.overview();const pref=overview.Memories.find(m=>m.Key==='teacher');if(pref&&teachers.some(t=>t.id===pref.Content))teacher.value=pref.Content}catch{/* answering remains usable */}
 }catch(e){error.value=messageOf(e)}finally{loading.value=false}
}
function reset(){if(busy.value||recognizing.value)return;clearImage();conversation.value='';messages.value=[];error.value='';sessionStorage.removeItem('408_conversation');followBottom.value=true;sidebarOpen.value=false}
async function selectConversation(id:string){if(busy.value||recognizing.value)return;clearImage();const c=history.value.find(c=>c.ID===id);if(!c)return;if(!bases.value.some(b=>b.ID===c.KnowledgeBaseID)){error.value='此会话所属知识库不在当前可用范围，不能继续提问';return};sidebarOpen.value=false;loading.value=true;try{const saved=await foundation.messages(id);conversation.value=id;active.value=c.KnowledgeBaseID;messages.value=saved.map(m=>({role:m.Role,content:m.Content,sources:m.Citations??[]}));sessionStorage.setItem('408_conversation',id)}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function rename(){const c=history.value.find(c=>c.ID===conversation.value);if(!c)return;const title=prompt('修改会话标题',c.Title);if(!title?.trim())return;try{await foundation.rename(c.ID,title);history.value=await foundation.conversations()}catch(e){error.value=messageOf(e)}}
async function remove(){if(!conversation.value||!confirm('删除此会话及聊天记录？'))return;try{await foundation.removeConversation(conversation.value);reset();history.value=await foundation.conversations()}catch(e){error.value=messageOf(e)}}
function onEnter(event:KeyboardEvent){if(event.isComposing||event.shiftKey)return;event.preventDefault();void send()}
function source(c:Citation){activeSource.value=c}
async function send(){
 const text=question.value.trim();if(!text||!active.value||busy.value||recognizing.value||loading.value||!status.value.enabled||imageFile.value&&!recognized.value)return
 if(text.length>4000){error.value='问题最多4000字，请裁剪题目或精简文字';return}
 busy.value=true;followBottom.value=true;error.value='';question.value='';stage.value='正在理解问题…';controller.value=new AbortController()
 messages.value.push({role:'user',content:text});const index=messages.value.length;messages.value.push({role:'assistant',content:''})
 try{await streamChat({KnowledgeBaseID:active.value,ConversationID:conversation.value,Question:text,Teacher:teacher.value},controller.value.signal,(event,data)=>{
 if(event==='status')stage.value=({understanding:'正在理解问题…',graph:'正在规划问题并查询图谱路径…',retrieving:'正在所选知识库中检索依据…',generating:'正在根据原文组织回答…',verifying:'正在核对回答与教材依据…'} as Record<string,string>)[(data as {stage:string}).stage]||'正在处理…'
 if(event==='reasoning')messages.value[index]!.reasoning=data as RetrievalTrace
 if(event==='understanding')messages.value[index]!.understanding=data as Understanding
 if(event==='delta')messages.value[index]!.content+=(data as {text:string}).text
 if(event==='done'){const result=data as ChatResult;conversation.value=result.ConversationID;sessionStorage.setItem('408_conversation',result.ConversationID);messages.value[index]={generation:result.Generation,related:result.RelatedQuestions??[],role:'assistant',content:result.Answer,sources:result.Sources??[],understanding:messages.value[index]?.understanding,reasoning:result.Reasoning??messages.value[index]?.reasoning};clearImage()}
 if(followBottom.value)void nextTick(()=>box.value?.scrollTo({top:box.value.scrollHeight,behavior:'auto'}))
 });history.value=await foundation.conversations()
 }catch(e){messages.value[index]!.incomplete=true;error.value=controller.value.signal.aborted?'已停止生成，本次回答可能未完成，请刷新历史记录确认（Generation stopped）':messageOf(e);messages.value[index]!.failure=error.value;question.value=text}
 finally{busy.value=false;stage.value=''}
}
onMounted(load);onBeforeUnmount(()=>{controller.value?.abort();clearImage()})

</script>
<template>
 <section class="assistant-workspace">
  <button v-if="sidebarOpen" class="sidebar-scrim" aria-label="关闭会话侧栏" @click="sidebarOpen=false" />
  <aside class="conversation-sidebar" :class="{open:sidebarOpen}" aria-label="历史会话">
   <div class="sidebar-top"><span class="workspace-mark">408 <small>学习助教</small></span><button class="icon-button mobile-close" aria-label="关闭会话侧栏" @click="sidebarOpen=false">×</button></div>
   <button class="new-chat" :disabled="busy||recognizing" @click="reset"><span>＋</span> 新对话 <small>↗</small></button>
   <input v-model="historySearch" class="history-search" type="search" aria-label="搜索历史会话" placeholder="搜索对话" />
   <div class="history-heading">最近对话 <small>{{visibleHistory.length}}</small></div>
   <nav class="conversation-list" aria-label="选择历史会话">
    <button v-for="c in visibleHistory" :key="c.ID" :class="{selected:conversation===c.ID}" :disabled="busy||recognizing||loading" :title="c.Title" @click="selectConversation(c.ID)"><span>{{c.Title}}</span></button>
    <p v-if="!visibleHistory.length" class="sidebar-empty">{{historySearch?'没有匹配的对话':'你的对话将保存在这里'}}</p>
   </nav>
   <div v-if="conversation" class="history-actions"><button :disabled="busy||recognizing" @click="rename">重命名</button><button :disabled="busy||recognizing" @click="remove">删除对话</button></div>
   <details v-if="auth.user?.role==='admin'" class="connection-tools"><summary>服务连接检测</summary><p>从后端检测短请求及较长合成输入，不发送用户资料；云端模型可能产生调用费用。</p><button :disabled="checking||busy" @click="checkConnection">{{checking?'检测中…':'检测检索与回答服务'}}</button><ul v-if="checkReport"><li v-for="c in checkReport.checks" :key="c.name">{{c.passed?'✓':'×'}} {{c.name}}：{{c.message}}</li></ul></details>
   <div class="sidebar-foot">教材优先 · 来源可追溯</div>
  </aside>
  <div class="conversation-main" role="region" aria-label="智能答疑">
   <header class="conversation-header"><div class="header-title"><button class="icon-button sidebar-toggle" aria-label="打开历史会话" @click="sidebarOpen=!sidebarOpen">☰</button><span>408 助教 <small>知识库问答</small></span></div><div class="header-controls"><select v-model="teacher" aria-label="选择老师风格" :disabled="busy" @change="saveTeacher"><option v-for="t in teachers" :key="t.id" :value="t.id">{{t.name}}</option></select><select v-model="active" aria-label="选择问答知识库" :disabled="busy||recognizing||loading||!bases.length" @change="reset"><option value="" disabled>{{loading?'加载中…':'选择知识库'}}</option><option v-for="kb in bases" :key="kb.ID" :value="kb.ID">{{kb.Name}}{{kb.IsPublic?'':' ＋ 公共教材'}}</option></select><button class="icon-button" aria-label="新对话" title="新对话" :disabled="busy||recognizing" @click="reset">＋</button></div></header>
   <div v-if="versionWarning" class="inline-alert" role="status">{{versionWarning}}</div>
   <div v-if="error" class="inline-alert error" role="alert">{{error}} <button v-if="!bases.length" @click="load">重新加载</button><button class="dismiss" aria-label="关闭错误提示" @click="error=''">×</button></div>
   <div v-if="!loading&&!status.enabled" class="inline-alert" role="status">{{status.message||'问答服务暂未启用，请联系管理员。'}}<button @click="load">重新检查</button></div>
   <div v-if="status.mode==='demo'" class="inline-alert" role="status">当前是资料片段预览，非 AI 回答。</div>
   <div ref="box" class="conversation-scroll" aria-live="polite" :aria-busy="busy" @scroll="onScroll">
    <section v-if="!messages.length" class="conversation-welcome"><div class="welcome-emblem">408</div><h1>今天想弄懂什么？</h1><p>从教材中寻找依据，把问题讲清楚。</p><div class="welcome-suggestions"><button :disabled="!active||loading||!status.enabled" @click="question='为什么需要虚拟内存？'">为什么需要虚拟内存？ <span>↗</span></button><button :disabled="!active||loading||!status.enabled" @click="question='TCP 如何实现可靠传输？'">TCP 如何实现可靠传输？ <span>↗</span></button><button :disabled="!active||loading||!status.enabled" @click="question='比较进程与线程的区别'">比较进程与线程的区别 <span>↗</span></button></div><RouterLink v-if="!loading&&!bases.length" to="/exam408/resources">先建立知识库并上传资料 →</RouterLink></section>
    <div v-else class="conversation-thread">
     <article v-for="(m,i) in messages" :key="i" class="thread-turn" :class="m.role">
      <div v-if="m.role==='user'" class="user-bubble">{{m.content}}</div>
      <template v-else><div class="assistant-avatar" aria-hidden="true">✦</div><div class="assistant-response">
       <details v-if="m.reasoning||m.understanding" class="retrieval-details"><summary>检索过程 <span v-if="m.reasoning?.Mode==='rag-degraded'" class="degraded-badge">图谱暂不可用</span><span v-else-if="m.reasoning?.Paths?.length">图谱＋文档</span><span v-else>文档检索</span></summary><p v-if="m.understanding">{{m.understanding.intent}}<span v-if="m.understanding.knowledge_points?.length"> · {{m.understanding.knowledge_points.join('、')}}</span></p><template v-if="m.reasoning"><p>{{m.reasoning.Notice}}</p><p>检索任务：{{m.reasoning.Subquestions.join('；')}}</p><ul><li v-for="(path,n) in m.reasoning.Paths.slice(0,8)" :key="n">{{path.Nodes.map(n=>n.Name).join(' ↔ ')}}</li></ul></template></details>
       <details v-if="auth.user?.role==='admin'&&m.generation" class="retrieval-details"><summary>生成诊断</summary><p>模型请求：{{m.generation.Attempted?'已发起':'未发起'}} · 返回文本：{{m.generation.ProviderReturned?'是':'否'}} · 原文核验：{{m.generation.Verified?'通过':'未通过'}}</p><p>整理轮数 {{m.generation.Attempts}} · 可引用事实 {{m.generation.Facts}}</p><p v-if="!m.generation.Verified">{{m.generation.Notice}} <code>{{m.generation.FailureCode}}</code></p></details><div class="response-text"><SafeAnswer :text="m.content" :citations="m.sources?.length??0" @cite="n=>m.sources?.[n]&&source(m.sources[n]!)"/></div>
       <span v-if="busy&&i===messages.length-1&&!m.content" class="thinking-indicator">{{stage||'正在查找资料…'}}<i /></span>
       <p v-if="m.incomplete" class="incomplete-note">{{m.failure||'连接中断，回答未完成，请重试。'}}</p>
       <details v-if="m.sources?.length" class="answer-sources"><summary><span>▤</span> 参考来源 <small>{{m.sources.length}}</small></summary><div class="source-grid"><button v-for="(s,n) in m.sources" :key="s.ChunkID+':'+n" @click="source(s)"><small>[{{n+1}}] {{s.Location||('第'+s.Page+'页')}}</small><strong>{{s.DocumentTitle}}</strong><span>{{s.Excerpt}}</span><em>查看原文 ↗</em></button></div></details>
       <details v-if="m.related?.length" class="related-exercises"><summary>同知识点练习与真题 <small>{{m.related.length}}</small></summary><article v-for="a in m.related" :key="a.ID"><b>{{a.Title}}</b><p>{{a.Payload.Stem}}</p><details><summary>选项与解析</summary><p v-for="(option,n) in a.Payload.Options" :key="n">{{String.fromCharCode(65+n)}}. {{option}}</p><p>{{a.Payload.Explanation}}</p><p v-for="(e,n) in a.Payload.Evidence??[]" :key="n"><button @click="openDocument(e.DocumentID,e.Page,e.RevisionID).catch(err=>error=messageOf(err))">{{e.DocumentTitle}} · 第{{e.Page}}页 ↗</button></p></details><RouterLink :to="{path:'/exam408/assessment',query:{asset:a.ID}}">去练习 →</RouterLink></article></details>
       <SpeakButton v-if="m.content&&!busy" :text="m.content"/><RouterLink v-if="m.content&&!busy" to="/exam408/learning">查看疑问记录与随堂教学 →</RouterLink><div v-if="m.content&&!busy" class="response-actions"><button title="复制回答" aria-label="复制回答" @click="copyAnswer(m.content)">⧉</button><button v-if="i===messages.length-1&&messages[i-1]?.role==='user'" :disabled="recognizing" @click="question=messages[i-1]!.content;send()">↻ 重新回答</button></div>
      </div></template>
     </article>
    </div>
   </div>
   <div class="composer-dock">
    <button v-if="!followBottom&&messages.length" class="scroll-bottom" aria-label="回到最新消息" @click="jumpToBottom">↓</button>
    <div class="composer-width">
     <div v-if="imageFile" class="attachment-preview"><img :src="imageURL" alt="待识别题目"/><div><strong>{{imageFile.name}}</strong><p>{{recognized?'识别完成，请核对下方题干和公式':'识别图片后核对题干，再发送问题'}}</p><button :disabled="recognizing||recognized||busy" @click="recognizeImage">{{recognizing?'识别中…':recognized?'已识别':'识别题目'}}</button></div><button class="icon-button" aria-label="移除图片" :disabled="recognizing||busy" @click="clearImage">×</button></div>
     <p v-for="warning in imageWarnings" :key="warning" class="image-warning">{{warning}}</p>
     <form class="chat-composer" @submit.prevent="send"><label class="sr-only" for="question">向助教提问或核对图片识别文字</label><textarea id="question" v-model="question" rows="2" :disabled="!active||busy||recognizing||loading" placeholder="向 408 助教提问，或添加题目图片…" @input="resizeInput" @keydown.enter="onEnter"/><div class="composer-tools"><label class="attach-control" title="添加题目图片"><span>＋</span><span class="attach-label">添加图片</span><input type="file" accept="image/png,image/jpeg" aria-label="添加题目图片" :disabled="busy||recognizing||loading||!active" @change="chooseImage"/></label><span class="composer-scope">{{bases.find(b=>b.ID===active)?.IsPublic?'教材优先':'公共教材＋个人资料'}}</span><button v-if="busy" type="button" class="send-control stop" aria-label="停止生成" @click="controller?.abort()">■</button><button v-else class="send-control" aria-label="发送问题" :disabled="!active||recognizing||!question.trim()||!status.enabled||loading||!!imageFile&&!recognized">↑</button></div></form>
     <div class="composer-foot"><span>回答附原文出处，请核对公式与推导。Shift＋Enter 换行</span><small title="界面版本">2026.11.08.2</small></div>
    </div>
   </div>
   <div v-if="copyNotice" class="copy-toast" role="status">{{copyNotice}}</div>
  </div>
  <CitationReader :source="activeSource" @close="activeSource=null"/>
 </section>
</template>
